import { CuratedProduct } from '../types';

const genId = () => Math.random().toString(36).substr(2, 9);

const createProduct = (
  platform: 'shopee' | 'tiktok',
  category: string,
  productId: string,
  title: string,
  price: number,
  commission: number,
  sales: number,
  rating: number,
  reviews: number,
  rank: number,
  badges: string[],
  imageUrl: string
): CuratedProduct => ({
  id: genId(),
  platform,
  category,
  product_id: productId,
  title,
  price,
  commission_rate: commission,
  sales_count: sales,
  rating,
  review_count: reviews,
  affiliate_link: `https://${platform}.shop/product/${productId}`,
  image_url: imageUrl,
  rank_number: rank,
  badges,
  curated_at: new Date().toISOString()
});

